const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const fs = require('fs');

(async () => {
  const browser = await chromium.launch();
  const errors = [];

  async function run(label, viewport, screenshot) {
    const context = await browser.newContext({ viewport, reducedMotion: 'no-preference' });
    const page = await context.newPage();
    page.on('console', m => { if (m.type() === 'error') errors.push(`${label} console: ${m.text()}`); });
    page.on('pageerror', e => errors.push(`${label} pageerror: ${e.message}`));
    await page.goto('http://127.0.0.1:3002/', { waitUntil: 'networkidle' });
    await page.evaluate(() => localStorage.clear());
    await page.reload({ waitUntil: 'networkidle' });

    // Add three names
    const names = ['Ada', 'Bo', 'Cy'];
    for (const n of names) {
      await page.fill('#nameInput', n);
      await page.press('#nameInput', 'Enter');
    }
    const chips = await page.locator('#chipList .chip, #chipList li').allTextContents();
    console.log(label, 'chips:', JSON.stringify(chips));
    await page.screenshot({ path: `screenshots/${screenshot}-setup.png`, fullPage: true });

    await page.click('#startBtn');
    await page.waitForSelector('#gamePanel:not([hidden])');

    const results = [];
    for (let i = 0; i < 3; i++) {
      const giver = (await page.locator('#giverName').innerText()).trim();
      // Wait for spin animation by watching overlay
      await page.click('#spinBtn');
      await page.waitForSelector('#revealOverlay:not([hidden])', { timeout: 15000 });
      const recipient = (await page.locator('#recipientName').innerText()).trim();
      const title = (await page.locator('#revealTitle').innerText()).trim();
      results.push({ giver, recipient, title });
      if (i === 2) await page.screenshot({ path: `screenshots/${screenshot}-final-reveal.png` });
      await page.click('#keepSecretBtn');
      if (i < 2) await page.waitForSelector('#revealOverlay[hidden]');
    }
    await page.waitForSelector('#finaleOverlay:not([hidden])', { timeout: 5000 });
    await page.screenshot({ path: `screenshots/${screenshot}-finale.png`, fullPage: true });
    console.log(label, 'results:', JSON.stringify(results));

    // Verify derangement
    const givers = results.map(r => r.giver).sort();
    const recipients = results.map(r => r.recipient).sort();
    const self = results.filter(r => r.giver === r.recipient);
    console.log(label, 'unique givers:', JSON.stringify(givers), 'unique recipients:', JSON.stringify(recipients), 'self matches:', self.length);

    // Host list
    await page.click('#hostListBtn');
    await page.waitForSelector('#hostDialog[open]');
    const hostRows = await page.locator('#hostList').innerText();
    console.log(label, 'host list:', JSON.stringify(hostRows));
    await page.screenshot({ path: `screenshots/${screenshot}-host.png` });

    // Resume test: reload while host dialog open is not ideal; close and test reload state at finale
    await page.keyboard.press('Escape');
    await page.reload({ waitUntil: 'networkidle' });
    const finaleVisible = await page.locator('#finaleOverlay:not([hidden])').count();
    console.log(label, 'resume at finale:', finaleVisible > 0);

    await context.close();
  }

  await run('desktop', { width: 1440, height: 950 }, 'smoke-desktop');
  await run('mobile', { width: 390, height: 844 }, 'smoke-mobile');

  console.log('ERRORS:', errors.length ? JSON.stringify(errors, null, 2) : 'none');
  await browser.close();
  if (errors.length) process.exit(1);
})();

