const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ viewport: { width: 390, height: 844 } });
  const page = await context.newPage();
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'networkidle' });
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: 'networkidle' });
  for (const n of ['Ada','Bo','Cy']) { await page.fill('#nameInput', n); await page.press('#nameInput','Enter'); }
  await page.click('#startBtn');
  await page.waitForSelector('#gamePanel:not([hidden])');
  console.log('SETUP/GAME', await page.evaluate(() => ({ scrollWidth: document.documentElement.scrollWidth, innerWidth: innerWidth, bodyScroll: document.body.scrollWidth, offenders: [...document.querySelectorAll('*')].filter(el => { const r = el.getBoundingClientRect(); return r.right > innerWidth + 1 || r.left < -1; }).slice(0,20).map(el => ({ tag: el.tagName, id: el.id, cls: el.className && String(el.className).slice(0,60), left: Math.round(el.getBoundingClientRect().left), right: Math.round(el.getBoundingClientRect().right), w: Math.round(el.getBoundingClientRect().width) })) })));

  for (let i = 0; i < 3; i++) {
    await page.click('#spinBtn');
    await page.waitForSelector('#revealOverlay:not([hidden])', { timeout: 15000 });
    if (i === 2) console.log('REVEAL', await page.evaluate(() => ({ scrollWidth: document.documentElement.scrollWidth, innerWidth, offenders: [...document.querySelectorAll('*')].filter(el => { const r = el.getBoundingClientRect(); return r.right > innerWidth + 1 || r.left < -1; }).slice(0,20).map(el => ({ tag: el.tagName, id: el.id, cls: el.className && String(el.className).slice(0,60), left: Math.round(el.getBoundingClientRect().left), right: Math.round(el.getBoundingClientRect().right), w: Math.round(el.getBoundingClientRect().width) })) })));
    await page.click('#keepSecretBtn');
    if (i < 2) await page.waitForFunction(() => document.getElementById('revealOverlay').hidden);
  }
  await page.waitForSelector('#finaleOverlay:not([hidden])');
  console.log('FINALE', await page.evaluate(() => ({ scrollWidth: document.documentElement.scrollWidth, innerWidth, bodyScroll: document.body.scrollWidth, offenders: [...document.querySelectorAll('*')].filter(el => { const r = el.getBoundingClientRect(); return r.right > innerWidth + 1 || r.left < -1; }).slice(0,25).map(el => ({ tag: el.tagName, id: el.id, cls: el.className && String(el.className).slice(0,60), left: Math.round(el.getBoundingClientRect().left), right: Math.round(el.getBoundingClientRect().right), w: Math.round(el.getBoundingClientRect().width) })) })));
  await browser.close();
})();

